  // &lt;...&gt;
  // For each step
  inline for (steps) |step| {
      // Add the library package
      step.addPackage(uv_pkg);
      // Link the libraries
      step.linkLibC();
      step.linkSystemLibrary("libuv");
      // Use the `stage1` compiler because of
      // https://github.com/ziglang/zig/issues/12325
      step.use_stage1 = true;
  }
  // &lt;...&gt;
}
```

